import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"54、【歸妹】 兌下震上","description":"橫渠易說 - 54、【歸妹】 兌下震上","frontmatter":{"title":"54、【歸妹】 兌下震上","description":"橫渠易說 - 54、【歸妹】 兌下震上"},"headers":[],"relativePath":"classics/hengqu/056.md","filePath":"classics/hengqu/056.md"}'),l={name:"classics/hengqu/056.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_54、【歸妹】-兌下震上" tabindex="-1">54、【歸妹】 兌下震上 <a class="header-anchor" href="#_54、【歸妹】-兌下震上" aria-label="Permalink to “54、【歸妹】 兌下震上”">​</a></h1><h3 id="彖曰-歸妹-天地之大義也-天地不交而萬物不興-歸妹-人之終始也-說以動-所歸妹也。-徵兇-位不當也-無攸利-柔乘剛也。" tabindex="-1">彖曰：歸妹，天地之大義也，天地不交而萬物不興，歸妹，人之終始也，說以動，所歸妹也。“徵兇”，位不當也；“無攸利”，柔乘剛也。 <a class="header-anchor" href="#彖曰-歸妹-天地之大義也-天地不交而萬物不興-歸妹-人之終始也-說以動-所歸妹也。-徵兇-位不當也-無攸利-柔乘剛也。" aria-label="Permalink to “彖曰：歸妹，天地之大義也，天地不交而萬物不興，歸妹，人之終始也，說以動，所歸妹也。“徵兇”，位不當也；“無攸利”，柔乘剛也。”">​</a></h3><p>泰之九三進而在四，六四降而在三，故曰“天地之大義”也。然泰道將終，徵將為否，故曰“兇”。 三五皆乘剛，必退反乃吉。 歸妹與革，均是澤為大卦，義不相乾，故革具四德而歸妹初不言德也。妹者是少女之稱也，對長男而言之，故言少女。先儒謂侄娣之義於卦不見，於爻辭則有君與娣之稱。長男而與長女，是人之常也；少女而與少男，是人之感也。說以動須是歸妹，聖人直是盡人情。</p><h3 id="象曰-澤上有雷-歸妹-君子以永終知敝。" tabindex="-1">象曰：澤上有雷，歸妹，君子以永終知敝。 <a class="header-anchor" href="#象曰-澤上有雷-歸妹-君子以永終知敝。" aria-label="Permalink to “象曰：澤上有雷，歸妹，君子以永終知敝。”">​</a></h3><p>永常禮之終，知人情之敝。</p><h3 id="初九-歸妹以娣-跛能履-徵吉。-象曰-歸妹以娣-以恆也-跛能履吉-相承也。" tabindex="-1">初九，歸妹以娣，跛能履，徵吉。 象曰：“歸妹以娣”，以恆也；“跛能履吉”，相承也。 <a class="header-anchor" href="#初九-歸妹以娣-跛能履-徵吉。-象曰-歸妹以娣-以恆也-跛能履吉-相承也。" aria-label="Permalink to “初九，歸妹以娣，跛能履，徵吉。 象曰：“歸妹以娣”，以恆也；“跛能履吉”，相承也。”">​</a></h3><p>陽處於上，不可不隨，故徵吉，以兌應震，合卦之義，常道也。爻為陽故能履，非匹故跛。</p><h3 id="九二-眇能視-利幽人之貞。-象曰-利幽人之貞-未變常也。" tabindex="-1">九二，眇能視，利幽人之貞。 象曰：“利幽人之貞”，未變常也。 <a class="header-anchor" href="#九二-眇能視-利幽人之貞。-象曰-利幽人之貞-未變常也。" aria-label="Permalink to “九二，眇能視，利幽人之貞。 象曰：“利幽人之貞”，未變常也。”">​</a></h3><p>震動乎上，雖匹而不至，所以眇，陽中，故能視。不援上，幽人之貞也。</p><h3 id="六三-歸妹以須-反歸以娣。-象曰-歸妹以須-未當也。" tabindex="-1">六三，歸妹以須，反歸以娣。 象曰：“歸妹以須”，未當也。 <a class="header-anchor" href="#六三-歸妹以須-反歸以娣。-象曰-歸妹以須-未當也。" aria-label="Permalink to “六三，歸妹以須，反歸以娣。 象曰：“歸妹以須”，未當也。”">​</a></h3><p>三陰本匯徵在上，今六三反下而為兌，故曰“歸妹以須，反歸以娣”。女當待年於家，今待年夫家而反歸，故曰“未當”。</p><h3 id="九四-歸妹愆期-遲歸有時。-象曰-愆期之志-有待而行也。" tabindex="-1">九四，歸妹愆期，遲歸有時。 象曰：愆期之志，有待而行也。 <a class="header-anchor" href="#九四-歸妹愆期-遲歸有時。-象曰-愆期之志-有待而行也。" aria-label="Permalink to “九四，歸妹愆期，遲歸有時。 象曰：愆期之志，有待而行也。”">​</a></h3><p>九四當速交而為泰，今獨後者，三有所待也，故曰“愆期”。</p><h3 id="六五-帝乙歸妹-其君之袂不如其娣之袂良-月幾望-吉。-象曰-帝乙歸妹-不如其娣之袂良也-其位在中-以貴行也。" tabindex="-1">六五，帝乙歸妹，其君之袂不如其娣之袂良，月幾望，吉。 象曰：“帝乙歸妹”，不如其娣之袂良也；其位在中，以貴行也。 <a class="header-anchor" href="#六五-帝乙歸妹-其君之袂不如其娣之袂良-月幾望-吉。-象曰-帝乙歸妹-不如其娣之袂良也-其位在中-以貴行也。" aria-label="Permalink to “六五，帝乙歸妹，其君之袂不如其娣之袂良，月幾望，吉。 象曰：“帝乙歸妹”，不如其娣之袂良也；其位在中，以貴行也。”">​</a></h3><p>歸妹，交泰之事備矣，與泰六五同，又於此見□□為之戒也。以其貴行，故戒其滿以幾望。一作又於此見新故之戒也。</p><h3 id="上六-女承筐無實-士刲羊無血-無攸利。-象曰-上六無實-承虛筐也。" tabindex="-1">上六，女承筐無實，士刲羊無血，無攸利。 象曰：上六無實，承虛筐也。 <a class="header-anchor" href="#上六-女承筐無實-士刲羊無血-無攸利。-象曰-上六無實-承虛筐也。" aria-label="Permalink to “上六，女承筐無實，士刲羊無血，無攸利。 象曰：上六無實，承虛筐也。”">​</a></h3><p>上六與六三皆陰，故士女無實。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
